def longestKDistinct(s, k):
    if k == 0:
        return 0
    cnt = {}
    left = 0
    best = 0
    for right, ch in enumerate(s):
        cnt[ch] = cnt.get(ch, 0) + 1
        while len(cnt) > k:
            c = s[left]
            cnt[c] -= 1
            if cnt[c] == 0:
                del cnt[c]
            left += 1
        best = max(best, right - left + 1)
    return best
